package media

import (
	"bytes"
	"embed"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/pion/webrtc/v3"
	"github.com/pion/webrtc/v3/pkg/media/ivfreader"
	"github.com/pion/webrtc/v3/pkg/media/oggreader"
)

// Media kinds.
const (
	KindAudio = "audio"
	KindVideo = "video"
)

// Content files, generated by scripts/gen-media.sh.
//
//go:embed assets/video.ivf assets/audio.ogg assets/video_90.ivf assets/video_180.ivf assets/video_720.ivf
var assets embed.FS

const (
	videoClockRate = 90000
	opusClockRate  = 48000
	opusFrame      = 20 * time.Millisecond
)

// OpusFrame is the duration of the audio packets the bots send.
const OpusFrame = opusFrame

// Frame is one encoded frame (video) or packet (audio) of the content.
type Frame struct {
	Data     []byte
	Duration time.Duration // Time until the next frame
	Samples  uint32        // Duration in RTP clock ticks (timestamp increment to the next frame)
}

// Content is pre-encoded media that bots loop. It is read-only and shared.
type Content struct {
	Kind         string
	Codec        webrtc.RTPCodecCapability
	Frames       []Frame
	LoopDuration time.Duration
	// Width and Height are the video's size from its IVF header (0 for
	// audio).
	Width, Height int
}

var (
	loadOnce sync.Once
	loaded   map[string]*Content
	loadErr  error
)

// LoadContent returns the built-in content for kind ("audio" or "video").
// The files are parsed once per process.
func LoadContent(kind string) (*Content, error) {
	loadOnce.Do(func() {
		loaded = map[string]*Content{}
		var c *Content
		if c, loadErr = loadVideo(); loadErr != nil {
			return
		}
		loaded[KindVideo] = c
		if c, loadErr = loadAudio(); loadErr != nil {
			return
		}
		loaded[KindAudio] = c
	})
	if loadErr != nil {
		return nil, loadErr
	}
	c, ok := loaded[kind]
	if !ok {
		return nil, fmt.Errorf("no media content for kind %q", kind)
	}
	return c, nil
}

// Simulcast layer files by height (specs/006-media-quality/research.md R6).
var layerFiles = map[int]string{90: "video_90.ivf", 180: "video_180.ivf", 360: "video.ivf", 720: "video_720.ivf"}

// Layer heights sent for each highest height (FR-010), low to high.
var layerSets = map[int][]int{360: {90, 180, 360}, 720: {180, 360, 720}}

var (
	layersMu     sync.Mutex
	loadedLayers = map[int]*Content{} // By height
)

// LoadLayers returns the three simulcast layers, low to high, whose highest
// is maxHeight lines (360 or 720). Every layer has the same frames timing
// and keyframes at the same frames, so they can be sent in lockstep.
func LoadLayers(maxHeight int) ([]*Content, error) {
	heights, ok := layerSets[maxHeight]
	if !ok {
		return nil, fmt.Errorf("no simulcast layers up to %d lines (360 or 720)", maxHeight)
	}
	layersMu.Lock()
	defer layersMu.Unlock()
	out := make([]*Content, 0, len(heights))
	for _, h := range heights {
		c := loadedLayers[h]
		if c == nil {
			var err error
			if h == 360 {
				c, err = LoadContent(KindVideo)
			} else {
				c, err = loadVideoFile(layerFiles[h])
			}
			if err != nil {
				return nil, fmt.Errorf("%d-line layer: %w", h, err)
			}
			loadedLayers[h] = c
		}
		out = append(out, c)
	}
	if err := checkAligned(out); err != nil {
		return nil, err
	}
	return out, nil
}

// LayerHeights returns the heights of the simulcast layers whose highest is
// maxHeight lines (360 or 720), low to high.
func LayerHeights(maxHeight int) ([]int, error) {
	heights, ok := layerSets[maxHeight]
	if !ok {
		return nil, fmt.Errorf("no simulcast layers up to %d lines (360 or 720)", maxHeight)
	}
	return append([]int(nil), heights...), nil
}

// checkAligned reports an error unless the layers have the same frame
// timing and keyframes at the same frames.
func checkAligned(out []*Content) error {
	for _, c := range out[1:] {
		if len(c.Frames) != len(out[0].Frames) || c.LoopDuration != out[0].LoopDuration {
			return fmt.Errorf("simulcast layers differ in length")
		}
		for i, f := range c.Frames {
			if f.Samples != out[0].Frames[i].Samples || isVP8Keyframe(f.Data) != isVP8Keyframe(out[0].Frames[i].Data) {
				return fmt.Errorf("simulcast layers not aligned at frame %d", i)
			}
		}
	}
	return nil
}

func loadVideo() (*Content, error) {
	return loadVideoFile("video.ivf")
}

func loadVideoFile(name string) (*Content, error) {
	data, err := assets.ReadFile("assets/" + name)
	if err != nil {
		return nil, err
	}
	return parseIVF(data)
}

// parseIVF reads VP8 content from an IVF file whose frames are all shown
// (no alt-ref frames), so they can be paced by their timestamps.
func parseIVF(data []byte) (*Content, error) {
	r, header, err := ivfreader.NewWith(bytes.NewReader(data))
	if err != nil {
		return nil, fmt.Errorf("video content: %w", err)
	}
	if header.FourCC != "VP80" {
		return nil, fmt.Errorf("video content: expected VP8, got %q", header.FourCC)
	}
	// IVF timestamps count timebase units of numerator/denominator seconds;
	// convert exactly, without rounding the unit first.
	num, den := uint64(header.TimebaseNumerator), uint64(header.TimebaseDenominator)
	toDuration := func(units uint64) time.Duration { return time.Duration(units * num * uint64(time.Second) / den) }
	toTicks := func(units uint64) uint32 { return uint32(units * num * videoClockRate / den) }
	c := &Content{
		Kind:   KindVideo,
		Codec:  webrtc.RTPCodecCapability{MimeType: webrtc.MimeTypeVP8, ClockRate: videoClockRate},
		Width:  int(header.Width),
		Height: int(header.Height),
	}
	var timestamps []uint64
	for {
		frame, fh, err := r.ParseNextFrame()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("video content: %w", err)
		}
		c.Frames = append(c.Frames, Frame{Data: frame})
		timestamps = append(timestamps, fh.Timestamp)
	}
	if len(c.Frames) < 2 {
		return nil, fmt.Errorf("video content: too few frames")
	}
	// Each frame lasts until the next one, the last one as long as the
	// previous one.
	units := make([]uint64, len(c.Frames))
	for i := range c.Frames {
		if i+1 < len(c.Frames) {
			units[i] = timestamps[i+1] - timestamps[i]
		} else {
			units[i] = units[i-1]
		}
		c.Frames[i].Duration = toDuration(units[i])
		c.LoopDuration += c.Frames[i].Duration
	}
	for i := range c.Frames {
		c.Frames[i].Samples = toTicks(units[i])
	}
	return c, nil
}

func loadAudio() (*Content, error) {
	data, err := assets.ReadFile("assets/audio.ogg")
	if err != nil {
		return nil, err
	}
	return parseOgg(data)
}

// parseOgg reads Opus content from an Ogg file holding one 20 ms packet per
// page.
func parseOgg(data []byte) (*Content, error) {
	r, header, err := oggreader.NewWith(bytes.NewReader(data))
	if err != nil {
		return nil, fmt.Errorf("audio content: %w", err)
	}
	if header.Channels == 0 {
		return nil, fmt.Errorf("audio content: invalid Opus header")
	}
	c := &Content{
		Kind:  KindAudio,
		Codec: webrtc.RTPCodecCapability{MimeType: webrtc.MimeTypeOpus, ClockRate: opusClockRate, Channels: 2},
	}
	for {
		page, _, err := r.ParseNextPage()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("audio content: %w", err)
		}
		if bytes.HasPrefix(page, []byte("OpusTags")) || len(page) == 0 {
			continue
		}
		// scripts/gen-media.sh and transcodeFile write one 20 ms packet per
		// page.
		c.Frames = append(c.Frames, Frame{Data: page, Duration: opusFrame, Samples: opusClockRate * uint32(opusFrame/time.Millisecond) / 1000})
		c.LoopDuration += opusFrame
	}
	if len(c.Frames) == 0 {
		return nil, fmt.Errorf("audio content: no packets")
	}
	return c, nil
}

// isVP8Keyframe reports whether a VP8 frame is a keyframe (RFC 6386 9.1:
// bit 0 of the frame tag is 0 for keyframes).
func isVP8Keyframe(frame []byte) bool {
	return len(frame) > 0 && frame[0]&0x01 == 0
}
